package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os/exec"
)

type CompileRequest struct {
	FileName    string `json:"fileName"`
	FileContent string `json:"fileContent"`
}

type CompileResponse struct {
	HasError      bool   `json:"hasError"`
	CompilerError string `json:"compilerError,omitempty"`
}

func compileHandler(w http.ResponseWriter, r *http.Request) {
	var req CompileRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request", http.StatusBadRequest)
		return
	}

	var cmd *exec.Cmd
	if req.FileName[len(req.FileName)-3:] == ".ts" {
		cmd = exec.Command("tsc", req.FileName)
	} else if req.FileName[len(req.FileName)-4:] == ".cpp" {
		cmd = exec.Command("g++", req.FileName, "-o", "output")
	} else {
		http.Error(w, "Unsupported file type", http.StatusBadRequest)
		return
	}

	// Create a temporary file to hold the code
	tmpFile, err := exec.Command("bash", "-c", fmt.Sprintf("echo '%s' > %s", req.FileContent, req.FileName)).Output()
	if err != nil {
		http.Error(w, "Failed to create temporary file", http.StatusInternalServerError)
		return
	}

	// Run the compilation command
	output, err := cmd.CombinedOutput()
	if err != nil {
		response := CompileResponse{
			HasError:      true,
			CompilerError: string(output),
		}
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(response)
		return
	}

	response := CompileResponse{
		HasError:      false,
		CompilerError: nil,
	}
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(response)
}

func main() {
	http.HandleFunc("/compile", compileHandler)
	fmt.Println("Server is running on http://0.0.0.0:5000")
	if err := http.ListenAndServe("0.0.0.0:5000", nil); err != nil {
		fmt.Println("Failed to start server:", err)
	}
}
